PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE shops (
  code TEXT PRIMARY KEY
    CHECK(length(code) = 4),

  name TEXT NOT NULL,
  owner_name TEXT NOT NULL,

  phone_number TEXT NOT NULL,
  whatsapp_number TEXT,
  email_address TEXT,

  address_line TEXT NOT NULL,
  city TEXT NOT NULL,
  state TEXT NOT NULL,
  postal_code TEXT NOT NULL,

  status TEXT NOT NULL DEFAULT 'active'
    CHECK(status IN ('pending', 'active', 'suspended')),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, latitude REAL
CHECK (
  latitude IS NULL OR
  (latitude >= -90 AND latitude <= 90)
), longitude REAL
CHECK (
  longitude IS NULL OR
  (longitude >= -180 AND longitude <= 180)
), state_code TEXT);
CREATE TABLE services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_code TEXT NOT NULL UNIQUE,
  service_type TEXT NOT NULL DEFAULT 'system'
    CHECK(service_type IN ('system', 'custom')),

  category TEXT NOT NULL,
  sub_category TEXT,

  name TEXT NOT NULL,
  description TEXT,

  icon TEXT,
  color TEXT,

  workflow_type TEXT NOT NULL DEFAULT 'generic'
    CHECK(
      workflow_type IN (
        'print',
        'upload',
        'assistance',
        'appointment',
        'payment',
        'generic'
      )
    ),

  /*
   * Custom services can belong to one shop.
   * System services leave owner_shop_code NULL.
   */
  owner_shop_code TEXT,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK(enabled IN (0, 1)),

  sort_order INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, homepage_order INTEGER
  CHECK (
    homepage_order IS NULL OR
    homepage_order >= 0
  ),

  FOREIGN KEY(owner_shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE
);
CREATE TABLE shop_services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,

  enabled INTEGER NOT NULL DEFAULT 0
    CHECK(enabled IN (0, 1)),

  display_name TEXT,
  description_override TEXT,
  icon_override TEXT,
  color_override TEXT,

  price_type TEXT NOT NULL DEFAULT 'contact'
    CHECK(
      price_type IN (
        'fixed',
        'starting_at',
        'per_page',
        'quote',
        'free',
        'contact'
      )
    ),

  price_amount_paise INTEGER
    CHECK(
      price_amount_paise IS NULL OR
      price_amount_paise >= 0
    ),

  price_note TEXT,

  sort_order INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, featured INTEGER NOT NULL DEFAULT 0,

  UNIQUE(shop_code, service_id),

  FOREIGN KEY(shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE,

  FOREIGN KEY(service_id)
    REFERENCES services(id)
    ON DELETE CASCADE
);
CREATE TABLE admin_login_codes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  email TEXT NOT NULL,
  code_hash TEXT NOT NULL,

  request_ip TEXT,

  expires_at TEXT NOT NULL,
  used_at TEXT,

  attempt_count INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  email TEXT NOT NULL,
  session_hash TEXT NOT NULL UNIQUE,

  expires_at TEXT NOT NULL,
  revoked_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE print_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  order_number TEXT NOT NULL UNIQUE,

  shop_code TEXT NOT NULL,

  customer_name TEXT NOT NULL,
  phone_number TEXT NOT NULL,
  email_address TEXT,
  whatsapp_number TEXT,
  whatsapp_consent INTEGER NOT NULL DEFAULT 0,

  estimated_pages INTEGER NOT NULL DEFAULT 1,
  copies INTEGER NOT NULL DEFAULT 1,

  color_mode TEXT NOT NULL,
  print_sides TEXT NOT NULL,
  paper_size TEXT NOT NULL,

  instructions TEXT,

  estimated_amount_rupees INTEGER,

  status TEXT NOT NULL DEFAULT 'submitted',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
);
CREATE TABLE print_request_files (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  print_request_id INTEGER NOT NULL,

  original_file_name TEXT NOT NULL,
  content_type TEXT,
  file_size INTEGER NOT NULL,

  storage_key TEXT,
  storage_status TEXT NOT NULL DEFAULT 'pending',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (print_request_id)
    REFERENCES print_requests(id)
    ON DELETE CASCADE
);
CREATE TABLE system_settings (
  setting_key TEXT PRIMARY KEY,
  setting_value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE service_sections (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_id INTEGER NOT NULL,

  section_key TEXT NOT NULL,
  label TEXT NOT NULL,

  description TEXT,

  visibility TEXT NOT NULL DEFAULT 'visible'
    CHECK (
      visibility IN (
        'visible',
        'hidden'
      )
    ),

  include_in_shop_email INTEGER NOT NULL DEFAULT 1,
  include_in_customer_email INTEGER NOT NULL DEFAULT 1,

  sort_order INTEGER NOT NULL DEFAULT 10,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE,

  UNIQUE (
    service_id,
    section_key
  )
);
CREATE TABLE service_fields (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  section_id INTEGER NOT NULL,

  field_key TEXT NOT NULL,
  label TEXT NOT NULL,

  field_type TEXT NOT NULL
    CHECK (
      field_type IN (
        'text',
        'textarea',
        'number',
        'email',
        'tel',
        'date',
        'select',
        'radio',
        'checkbox',
        'checkbox-group',
        'file'
      )
    ),

  requirement TEXT NOT NULL DEFAULT 'optional'
    CHECK (
      requirement IN (
        'mandatory',
        'optional',
        'hidden'
      )
    ),

  placeholder TEXT,
  help_text TEXT,

  default_value TEXT,

  options_json TEXT,
  validation_json TEXT,

  email_label TEXT,

  include_in_shop_email INTEGER NOT NULL DEFAULT 1,
  include_in_customer_email INTEGER NOT NULL DEFAULT 1,
  include_in_request_view INTEGER NOT NULL DEFAULT 1,

  sort_order INTEGER NOT NULL DEFAULT 10,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (section_id)
    REFERENCES service_sections(id)
    ON DELETE CASCADE,

  UNIQUE (
    section_id,
    field_key
  )
);
CREATE TABLE service_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  request_number TEXT NOT NULL UNIQUE,

  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,

  customer_name TEXT,
  phone_number TEXT,
  email_address TEXT,
  whatsapp_number TEXT,
  whatsapp_consent INTEGER NOT NULL DEFAULT 0,

  status TEXT NOT NULL DEFAULT 'submitted',

  details_json TEXT NOT NULL DEFAULT '{}',

  estimated_amount_paise INTEGER,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (shop_code)
    REFERENCES shops(code),

  FOREIGN KEY (service_id)
    REFERENCES services(id)
);
CREATE TABLE service_request_files (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_request_id INTEGER NOT NULL,

  section_key TEXT NOT NULL,
  field_key TEXT NOT NULL,

  original_file_name TEXT NOT NULL,
  content_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,

  storage_key TEXT NOT NULL UNIQUE,
  storage_status TEXT NOT NULL DEFAULT 'stored',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_request_id)
    REFERENCES service_requests(id)
    ON DELETE CASCADE
);
CREATE TABLE service_market_prices (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_id INTEGER NOT NULL,

  country_code TEXT NOT NULL,
  currency_code TEXT NOT NULL,

  price_type TEXT NOT NULL DEFAULT 'starting_at'
    CHECK (
      price_type IN (
        'fixed',
        'starting_at',
        'per_page',
        'quote',
        'free',
        'contact'
      )
    ),

  amount_minor INTEGER
    CHECK (
      amount_minor IS NULL OR
      amount_minor >= 0
    ),

  price_note TEXT,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK (enabled IN (0, 1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE,

  UNIQUE(service_id, country_code)
);
CREATE TABLE daily_puzzles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  puzzle_date TEXT NOT NULL,
  puzzle_number INTEGER NOT NULL,

  stage TEXT NOT NULL
    CHECK (
      stage IN (
        '5x5',
        '7x7'
      )
    ),

  board_size INTEGER NOT NULL,
  max_moves INTEGER NOT NULL,
  mystery_count INTEGER NOT NULL,

  /*
   * What the player receives.
   */
  start_board_json TEXT NOT NULL,

  /*
   * Admin/debug only.
   */
  solved_board_json TEXT NOT NULL,

  /*
   * Admin/hint-engine only.
   */
  solution_moves_json TEXT NOT NULL,

  /*
   * Server-side reveal sequence.
   */
  mystery_reveal_order_json TEXT NOT NULL,

  verified INTEGER
    NOT NULL
    DEFAULT 0,

  status TEXT
    NOT NULL
    DEFAULT 'draft'
    CHECK (
      status IN (
        'draft',
        'published',
        'retired'
      )
    ),

  created_at TEXT
    NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT
    NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    puzzle_date,
    stage
  ),

  UNIQUE (
    puzzle_number,
    stage
  )
);
CREATE TABLE puzzle_winners (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  puzzle_number INTEGER NOT NULL,
  puzzle_date TEXT NOT NULL,

  name TEXT NOT NULL,
  email TEXT NOT NULL,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    puzzle_number,
    email
  )
);
CREATE TABLE featured_promotions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  source_type TEXT NOT NULL
    CHECK (
      source_type IN (
        'gyan',
        'groupon',
        'woot',
        'affiliate',
        'default'
      )
    ),

  title TEXT NOT NULL,
  description TEXT,

  icon TEXT,
  image_url TEXT,

  cta_label TEXT NOT NULL DEFAULT 'View',

  target_url TEXT,

  service_code TEXT,
  shop_code TEXT,

  latitude REAL,
  longitude REAL,
  radius_km REAL,

  starts_at TEXT,
  ends_at TEXT,

  priority INTEGER NOT NULL DEFAULT 0,

  enabled INTEGER NOT NULL DEFAULT 1,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, offer_text TEXT, discount_percent REAL);
CREATE TABLE advertisement_submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  status TEXT NOT NULL DEFAULT 'pending_email_verification'
    CHECK (
      status IN (
        'pending_email_verification',
        'pending_review',
        'approved',
        'rejected'
      )
    ),

  business_name TEXT NOT NULL,
  service_name TEXT NOT NULL,

  offer_text TEXT,
  discount_percent REAL,

  latitude REAL NOT NULL,
  longitude REAL NOT NULL,

  service_radius_km REAL NOT NULL,

  phone TEXT NOT NULL,
  email TEXT NOT NULL,

  verification_token_hash TEXT,
  verification_expires_at TEXT,

  email_verified_at TEXT,
  approved_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, admin_review_token_hash TEXT, admin_review_expires_at TEXT, duration_days INTEGER NOT NULL DEFAULT 7, description TEXT, featured_promotion_id INTEGER, delete_token_hash TEXT, delete_token_expires_at TEXT, deleted_at TEXT, city TEXT, region TEXT, region_code TEXT, country_code TEXT, postal_code TEXT);
CREATE TABLE local_service_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  status TEXT NOT NULL DEFAULT 'pending_email_verification',

  service_name TEXT NOT NULL,

  details TEXT,

  latitude REAL NOT NULL,
  longitude REAL NOT NULL,

  search_radius_km REAL NOT NULL,

  email TEXT NOT NULL,
  phone TEXT,

  preferred_time TEXT,

  verification_token_hash TEXT,
  verification_expires_at TEXT,

  email_verified_at TEXT,

  assigned_shop_code TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, city TEXT, region TEXT, region_code TEXT, country_code TEXT, postal_code TEXT);
CREATE TABLE daily_analytics (
  analytics_date TEXT NOT NULL,
  country_code TEXT NOT NULL DEFAULT '',
  region TEXT NOT NULL DEFAULT '',
  city TEXT NOT NULL DEFAULT '',
  latitude REAL,
  longitude REAL,
  unique_visitors INTEGER NOT NULL DEFAULT 0,
  visits INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (analytics_date, country_code, region, city)
);
CREATE TABLE daily_analytics_visitors (
  analytics_date TEXT NOT NULL,
  visitor_hash TEXT NOT NULL,
  country_code TEXT NOT NULL DEFAULT '',
  region TEXT NOT NULL DEFAULT '',
  city TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (analytics_date, visitor_hash)
);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at TEXT, last_city TEXT, last_region TEXT, last_region_code TEXT, last_country_code TEXT, last_postal_code TEXT, last_location_at TEXT);
CREATE TABLE auth_magic_links (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE chat_threads (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id INTEGER NOT NULL UNIQUE,
  customer_user_id INTEGER,
  shop_code TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (request_id) REFERENCES service_requests(id),
  FOREIGN KEY (customer_user_id) REFERENCES users(id)
);
CREATE TABLE chat_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  thread_id INTEGER NOT NULL,
  sender_type TEXT NOT NULL,
  sender_user_id INTEGER,
  sender_shop_code TEXT,
  message TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (thread_id) REFERENCES chat_threads(id),
  FOREIGN KEY (sender_user_id) REFERENCES users(id)
);
CREATE TABLE offline_shop_codes (
  code TEXT PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'reserved'
    CHECK (status IN ('reserved','claimed')),
  batch_code TEXT NOT NULL,
  claimed_shop_code TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  claimed_at TEXT,
  CHECK (length(code)=4),
  CHECK (substr(code,3,1)='R')
);
CREATE TABLE shop_featured_services (
  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,
  featured_order INTEGER NOT NULL
    CHECK (featured_order BETWEEN 1 AND 3),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (shop_code, service_id),
  UNIQUE (shop_code, featured_order),

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE
);
CREATE TABLE puzzle_results (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  result_id TEXT NOT NULL,

  puzzle_number INTEGER NOT NULL,
  puzzle_date TEXT NOT NULL,
  stage TEXT NOT NULL
    CHECK (
      stage IN (
        '5x5',
        '7x7'
      )
    ),

  gq_score INTEGER NOT NULL,
  moves_used INTEGER NOT NULL,

  icons_json TEXT NOT NULL
    DEFAULT '[]',

  skill_stats_json TEXT NOT NULL
    DEFAULT '{}',

  name TEXT,
  email TEXT,

  claimed INTEGER NOT NULL
    DEFAULT 0
    CHECK (
      claimed IN (
        0,
        1
      )
    ),

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    puzzle_number,
    stage,
    result_id
  )
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_shops_city
  ON shops(city);
CREATE INDEX idx_shops_status
  ON shops(status);
CREATE INDEX idx_services_category
  ON services(category, sub_category);
CREATE INDEX idx_services_type
  ON services(service_type);
CREATE INDEX idx_services_owner_shop
  ON services(owner_shop_code);
CREATE INDEX idx_shop_services_shop
  ON shop_services(shop_code);
CREATE INDEX idx_shop_services_enabled
  ON shop_services(shop_code, enabled);
CREATE INDEX idx_admin_login_codes_email
  ON admin_login_codes (
    email,
    created_at
  );
CREATE INDEX idx_admin_login_codes_ip
  ON admin_login_codes (
    request_ip,
    created_at
  );
CREATE INDEX idx_admin_sessions_hash
  ON admin_sessions (
    session_hash
  );
CREATE INDEX idx_print_requests_shop_code
ON print_requests(shop_code);
CREATE INDEX idx_print_requests_status
ON print_requests(status);
CREATE INDEX idx_print_requests_created_at
ON print_requests(created_at);
CREATE INDEX idx_print_request_files_request_id
ON print_request_files(print_request_id);
CREATE INDEX idx_print_request_files_storage_cleanup
ON print_request_files (
  storage_status,
  created_at
);
CREATE INDEX idx_service_sections_service
ON service_sections (
  service_id,
  sort_order
);
CREATE INDEX idx_service_fields_section
ON service_fields (
  section_id,
  sort_order
);
CREATE INDEX idx_service_requests_shop_created
ON service_requests (
  shop_code,
  created_at DESC
);
CREATE INDEX idx_service_requests_service_created
ON service_requests (
  service_id,
  created_at DESC
);
CREATE INDEX idx_service_requests_status
ON service_requests (
  status,
  created_at DESC
);
CREATE INDEX idx_service_request_files_request
ON service_request_files (
  service_request_id
);
CREATE INDEX idx_services_homepage_order
ON services (
  category,
  enabled,
  homepage_order
);
CREATE INDEX idx_service_market_prices_lookup
ON service_market_prices (
  service_id,
  country_code,
  enabled
);
CREATE INDEX idx_shops_location
ON shops (
  status,
  state,
  city,
  latitude,
  longitude
);
CREATE INDEX idx_daily_puzzles_number
ON daily_puzzles (
  puzzle_number
);
CREATE INDEX idx_daily_puzzles_date
ON daily_puzzles (
  puzzle_date
);
CREATE INDEX idx_daily_puzzles_status
ON daily_puzzles (
  status
);
CREATE INDEX idx_puzzle_winners_number
ON puzzle_winners (
  puzzle_number
);
CREATE INDEX idx_puzzle_winners_email
ON puzzle_winners (
  email
);
CREATE INDEX idx_puzzle_winners_date
ON puzzle_winners (
  puzzle_date
);
CREATE INDEX idx_featured_promotions_active
ON featured_promotions (
  enabled,
  starts_at,
  ends_at,
  priority
);
CREATE INDEX idx_featured_promotions_location
ON featured_promotions (
  latitude,
  longitude
);
CREATE INDEX idx_shop_services_featured
ON shop_services (
  shop_code,
  featured,
  enabled
);
CREATE INDEX idx_featured_promotions_ranking
ON featured_promotions (
  enabled,
  priority,
  discount_percent
);
CREATE INDEX idx_advertisement_submissions_status
ON advertisement_submissions (
  status,
  created_at
);
CREATE INDEX idx_advertisement_submissions_email
ON advertisement_submissions (
  email
);
CREATE INDEX idx_local_service_requests_status
ON local_service_requests (
  status,
  created_at
);
CREATE INDEX idx_local_service_requests_email
ON local_service_requests (
  email
);
CREATE INDEX idx_local_service_requests_assignment
ON local_service_requests (
  assigned_shop_code,
  status
);
CREATE INDEX idx_daily_analytics_date
ON daily_analytics (analytics_date);
CREATE INDEX idx_daily_analytics_geo
ON daily_analytics (country_code, region, city, analytics_date);
CREATE INDEX idx_daily_analytics_visitors_created
ON daily_analytics_visitors (analytics_date);
CREATE INDEX idx_auth_magic_links_email ON auth_magic_links(email);
CREATE INDEX idx_auth_magic_links_expires ON auth_magic_links(expires_at);
CREATE INDEX idx_user_sessions_user ON user_sessions(user_id);
CREATE INDEX idx_user_sessions_expires ON user_sessions(expires_at);
CREATE INDEX idx_chat_threads_customer
  ON chat_threads(customer_user_id, updated_at DESC);
CREATE INDEX idx_chat_threads_shop
  ON chat_threads(shop_code, updated_at DESC);
CREATE INDEX idx_chat_messages_thread
  ON chat_messages(thread_id, id);
CREATE INDEX idx_offline_shop_codes_status
ON offline_shop_codes(status);
CREATE INDEX idx_offline_shop_codes_batch
ON offline_shop_codes(batch_code);
CREATE INDEX idx_shop_featured_services_shop
ON shop_featured_services (
  shop_code,
  featured_order
);
CREATE INDEX idx_puzzle_results_rank
ON puzzle_results (
  puzzle_number,
  stage,
  gq_score DESC,
  moves_used ASC,
  created_at ASC
);
CREATE INDEX idx_puzzle_results_email
ON puzzle_results (
  email
);
CREATE INDEX idx_puzzle_results_date
ON puzzle_results (
  puzzle_date
);
